import type { DirEntry } from '@shared/types'
import manifest from './file-icons.json'

/**
 * Material Icon Theme icons (MIT), as in VS Code and Cursor: one per language, well-known file name and folder name.
 * Regenerated by `node scripts/file-icons.mjs`; the SVGs are served from `public/file-icons`.
 */
interface IconManifest {
  file: string
  folder: string
  folderOpen: string
  ext: Record<string, string>
  names: Record<string, string>
  folders: Record<string, [string, string]>
}

const icons = manifest as unknown as IconManifest

/** Exact file name first, then the longest extension (`foo.d.ts`: `d.ts` before `ts`). */
export function fileIconId(name: string): string {
  const lower = name.toLowerCase()
  const byName = icons.names[lower]
  if (byName) return byName
  for (let dot = lower.indexOf('.'); dot !== -1; dot = lower.indexOf('.', dot + 1)) {
    const byExt = icons.ext[lower.slice(dot + 1)]
    if (byExt) return byExt
  }
  return icons.file
}

/** Folder icon by its own name (the last segment of a merged `lib/deep`). */
export function folderIconId(name: string, expanded: boolean): string {
  const own = name.slice(name.lastIndexOf('/') + 1).toLowerCase()
  const pair = icons.folders[own]
  if (pair) return pair[expanded ? 1 : 0]
  return expanded ? icons.folderOpen : icons.folder
}

export function EntryIcon({ entry, expanded }: { entry: Pick<DirEntry, 'name' | 'isDirectory'>; expanded?: boolean }) {
  const id = entry.isDirectory ? folderIconId(entry.name, !!expanded) : fileIconId(entry.name)
  return <img src={`./file-icons/${id}.svg`} alt="" width={16} height={16} draggable={false} className="pointer-events-none size-4 shrink-0" />
}
